// Differential runner: replays a corpus of argv arrays against both the Python
// executable and the Node port and reports byte-level divergences.
// Usage: node diff.mjs corpus.json [maxExamples]
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test12_executable';
const NODE_ENTRY = '/output/test12.mjs';

// The two programs legitimately report different prog names in usage/error text
// (basename of argv[0], exactly as Python does), so normalise that one token.
const normalise = (text) => text.split('test12_executable').join('%PROG%').split('test12.mjs').join('%PROG%');

function run(cmd, argv) {
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

const corpus = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const maxExamples = Number(process.argv[3] ?? 8);
const mismatches = [];

for (const argv of corpus) {
  const expected = run([EXE], argv);
  const actual = run(['node', NODE_ENTRY], argv);
  const same =
    normalise(expected.out) === normalise(actual.out) &&
    normalise(expected.err) === normalise(actual.err) &&
    expected.code === actual.code;
  if (!same) mismatches.push({ argv, expected, actual });
}

console.log(`total=${corpus.length} mismatches=${mismatches.length}`);
for (const m of mismatches.slice(0, maxExamples)) {
  console.log(JSON.stringify(m));
}

