import { bech32Encode, segwitEncode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const DIGITS = [...CHARSET].map((c,i)=>[c,i]).filter(([c])=>/[0-9]/.test(c)).map(([,i])=>i);
