// Generates /tmp/corpus/case-variants.json -- a JSON array of argv arrays.
// Family: case handling (whole-string case, per-position single-char flips,
// wrong-case --a hrp, uncased hrps, non-ASCII cased characters, flag casing).
import { writeFileSync, mkdirSync } from 'node:fs';
import { segwitEncode } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
}
const push = (a, b) => add(['--a', a, '--b', b]);

const swap = (s) =>
  [...s].map((c) => (c >= 'a' && c <= 'z' ? c.toUpperCase() : c >= 'A' && c <= 'Z' ? c.toLowerCase() : c)).join('');
const isCased = (c) => /[A-Za-z]/.test(c);
const flipAt = (s, i) => s.slice(0, i) + swap(s[i]) + s.slice(i + 1);

// witprog [1,2] -> witver 1, prints "1\n[8, 128]" (a live, non-None payload)
const mk = (hrp) => segwitEncode(hrp, 1, [1, 2]);

const BASES = [
  // known-good vectors straight out of the spec
  { hrp: 'bc', addr: 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4' },
  { hrp: 'bc', addr: 'bc1pqypqj3p230' },
  { hrp: 'bc', addr: 'bc1qqypqxpq9qcrsszg2pvxq6rs0zqg3yyc5fcj4z3' },
  { hrp: 'tb', addr: 'tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sl5k7' },
  { hrp: 'bc', addr: 'bc1sw50qa3jx3s' },
  { hrp: 'bc', addr: 'bc1zw508d6qejxtdg4y5r3zarvaryvg6kdaj' },
  { hrp: 'bc', addr: 'bc1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq9e75rs' },
  { hrp: 'bc', addr: 'bc1sru0s6wgyhl' },
  { hrp: 'bc', addr: 'bc19qypqxpq9vu00uz' },
  { hrp: 'bc', addr: 'bc1pw508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7k7grplx' },
  // hrps with no cased characters at all
  { hrp: '123', addr: '1231pqypqa3aq5z' },
  { hrp: '~', addr: '~1pqypqmsvv26' },
  { hrp: '!', addr: '!1pqypqkwt0yt' },
  { hrp: '9', addr: mk('9') },
  { hrp: '_', addr: mk('_') },
  { hrp: '0', addr: mk('0') },
  { hrp: '+-*/', addr: mk('+-*/') },
  { hrp: '\\', addr: mk('\\') },
  { hrp: '"', addr: mk('"') },
  { hrp: "'", addr: mk("'") },
  // rfind picks the LAST '1' -> hrp may itself contain '1'
  { hrp: 'a1b', addr: 'a1b1pqypqkphs7v' },
  { hrp: 'Ab1cD', addr: mk('Ab1cD') },
  // single-letter and dotted-i-ish hrps
  { hrp: 'i', addr: mk('i') },
  { hrp: 'k', addr: mk('k') },
  { hrp: 's', addr: mk('s') },
  // hrps that are themselves upper / mixed case (checksum baked over those ords)
  { hrp: 'I', addr: mk('I') },
  { hrp: 'K', addr: mk('K') },
  { hrp: 'S', addr: mk('S') },
  { hrp: 'BC', addr: mk('BC') },
  { hrp: 'Bc', addr: mk('Bc') },
  { hrp: 'bC', addr: mk('bC') },
  { hrp: 'iI', addr: mk('iI') },
  { hrp: 'zZz', addr: mk('zZz') },
  // an address with NO cased characters anywhere (lower(s)==s AND upper(s)==s)
  { hrp: '1', addr: '11988662099454' },
  { hrp: '1', addr: '11905972572450' },
  { hrp: '1', addr: '11965985082298' },
];

for (const { hrp, addr } of BASES) {
  const hrpForms = [hrp, hrp.toLowerCase(), hrp.toUpperCase(), swap(hrp), flipAt(hrp, 0)];
  const addrForms = [addr, addr.toLowerCase(), addr.toUpperCase(), swap(addr)];
  // whole-string case cross product: right/wrong-case hrp x right/wrong-case addr
  for (const h of hrpForms) for (const a of addrForms) push(h, a);

  // single-character flips at every position, in both directions:
  // from the all-lower form (each flip introduces one upper char) and from the
  // all-upper form (each flip introduces one lower char), plus the original.
  const lower = addr.toLowerCase();
  const upper = addr.toUpperCase();
  for (const base of new Set([lower, upper, addr])) {
    for (let i = 0; i < base.length; i += 1) {
      if (!isCased(base[i])) continue;
      const flipped = flipAt(base, i);
      push(hrp, flipped);
      push(hrp.toLowerCase(), flipped);
    }
  }
  // a few flips paired with an upper-case / swapped hrp argument
  for (let i = 0; i < Math.min(lower.length, 4); i += 1) {
    push(hrp.toUpperCase(), flipAt(lower, i));
    push(swap(hrp), flipAt(upper, i));
  }
}

// ---- non-ASCII cased characters -------------------------------------------
// Every one of these is rejected by the ord<33/ord>126 test *before* any
// case comparison happens, so lowering must not run first. U+212A lowercases
// to 'k', U+017F uppercases to 'S', U+0130 lowercases to a TWO-code-point
// string, U+FB01 uppercases to "FI" -- all length- or content-changing.
const WEIRD = ['K', 'ſ', 'İ', 'ı', 'ﬁ', 'ß', 'Å', 'А', 'ａ', 'ẞ'];
for (const w of WEIRD) {
  const base = 'bc1pqypqj3p230';
  push('bc', w + base.slice(1));
  push('bc', base + w);
  push('bc', base.slice(0, 3) + w + base.slice(4));
  push('bc', base.toUpperCase() + w);
  push('bc', w + base.toUpperCase().slice(1));
  push(w, mk('k'));
  push(w, mk('k').toUpperCase());
  push(w.toLowerCase(), mk('k'));
  push(w.toUpperCase(), mk('s'));
}

// ---- assorted hand-picked case edges --------------------------------------
const EXTRA = [
  ['', '1PQYPQDTQ4FH'],
  ['', '1pqypqdtq4fh'],
  ['1', '1PQYPQDTQ4FH'],
  ['bc', 'BC1PQYPQJ3P230'],
  ['BC', 'BC1PQYPQJ3P230'],
  ['bc', 'bc1PQYPQJ3P230'],
  ['bc', 'BC1pqypqj3p230'],
  ['bC', 'bC1pqypqj3p230'],
  ['bc', 'bc1pqypqj3p23O'],
  ['bc', 'Bc1PQYPQJ3P230'],
  ['bc', 'bC1PQYPQJ3P230'],
  ['bc', '1PQYPQJ3P230'],
  ['bc', 'BC1'],
  ['bc', 'BC'],
  ['BC', 'bc'],
  ['bc', '1'],
  ['bc', 'BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4'],
  ['BC', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4'],
  ['Bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4'],
  ['tb', 'TB1QRP33G0Q5C5TXSP9ARYSRX4K6ZDKFS4NCE4XJ0GDCCCEFVPYSXF3Q0SL5K7'],
  ['TB', 'TB1QRP33G0Q5C5TXSP9ARYSRX4K6ZDKFS4NCE4XJ0GDCCCEFVPYSXF3Q0SL5K7'],
  ['123', '1231PQYPQA3AQ5Z'],
  ['123', '1231pqypqa3aq5z'],
  ['123', '1231PQYPQA3aQ5Z'],
  ['~', '~1PQYPQMSVV26'],
  ['!', '!1PQYPQKWT0YT'],
  ['a1b', 'A1B1PQYPQKPHS7V'],
  ['A1B', 'A1B1PQYPQKPHS7V'],
  ['a1b', 'a1B1PQYPQKPHS7V'],
  ['1', '11988662099454'],
  ['1', '11988662099455'],
  ['bc', 'bc1pqypqj3p230 '],
  ['bc', ' bc1pqypqj3p230'],
  ['bc', 'BC1PQYPQJ3P230 '],
  ['bc', 'bc1PQYPQJ3P230 '],
];
for (const [a, b] of EXTRA) push(a, b);

// ---- flag / option casing -------------------------------------------------
const FLAGS = [
  ['--A', 'bc', '--b', 'bc1pqypqj3p230'],
  ['--a', 'bc', '--B', 'bc1pqypqj3p230'],
  ['--A', 'bc', '--B', 'bc1pqypqj3p230'],
  ['--a', 'bc', '--b', 'bc1pqypqj3p230', '--A', 'x'],
  ['--a=BC', '--b=BC1PQYPQJ3P230'],
  ['--a=bc', '--b=BC1PQYPQJ3P230'],
  ['--A=bc', '--b', 'bc1pqypqj3p230'],
  ['--a', 'bc', '--b', 'bc1pqypqj3p230', '--a', 'BC'],
  ['--a', 'BC', '--b', 'bc1pqypqj3p230', '--a', 'bc'],
  ['-H'],
  ['--H'],
  ['--Help'],
  ['--HELP'],
  ['-h'],
  ['--help'],
  ['-Hh'],
  ['-hH'],
  ['--A'],
  ['--a', 'BC'],
  ['--B', 'BC1PQYPQJ3P230'],
];
for (const f of FLAGS) add(f);

mkdirSync('/tmp/corpus', { recursive: true });
writeFileSync('/tmp/corpus/case-variants.json', `${JSON.stringify(cases)}\n`);
console.log('cases:', cases.length);

