// ---- exhaustive single-character HRP sweep --------------------------------
// Every printable ASCII code point 33..126 as a one-character HRP, each paired
// with the address generated for it, in as-is / lower / upper forms on both
// sides. This covers "hrp with no cased characters at all" exhaustively and
// "--a in the wrong case" for every cased and uncased character alike.
for (let code = 33; code <= 126; code += 1) {
  const c = String.fromCharCode(code);
  const addr = mk(c);
  if (addr === null) continue;
  for (const h of new Set([c, c.toLowerCase(), c.toUpperCase()])) {
    for (const a of new Set([addr, addr.toLowerCase(), addr.toUpperCase()])) push(h, a);
  }
}

// ---- two-character HRP case combinations ---------------------------------
for (const pair of ['aa', 'aA', 'Aa', 'AA', 'a1', 'A1', '1a', '1A', 'kK', 'Kk', 'sS', 'Ss', 'iI', 'Ii']) {
  const addr = mk(pair);
  for (const h of new Set([pair, pair.toLowerCase(), pair.toUpperCase(), swap(pair)])) {
    for (const a of new Set([addr, addr.toLowerCase(), addr.toUpperCase(), swap(addr)])) push(h, a);
  }
}

// ---- HRP length boundary (83 / 84) crossed with case ----------------------
for (const n of [82, 83, 84]) {
  for (const letter of ['a', 'A']) {
    const hrp = letter.repeat(n);
    for (const prog of [[1, 2], new Array(40).fill(1)]) {
      const addr = segwitEncode(hrp, 1, prog);
      if (addr === null) continue;
      for (const h of new Set([hrp, hrp.toLowerCase(), hrp.toUpperCase()])) {
        for (const a of new Set([addr, addr.toLowerCase(), addr.toUpperCase()])) push(h, a);
      }
      // flip exactly one character on either side of the separator
      const lo = addr.toLowerCase();
      const up = addr.toUpperCase();
      for (const base of [lo, up]) {
        for (const i of [0, 1, n - 2, n - 1, n, n + 1, n + 2, base.length - 2, base.length - 1]) {
          if (i < 0 || i >= base.length || !isCased(base[i])) continue;
          push(hrp.toLowerCase(), flipAt(base, i));
        }
      }
    }
  }
}

// ---- uppercase forms of the spec's "no output" vectors --------------------
const NEGATIVES = [
  ['bc', 'bc1p6xlxuzj6dwac8v78ka6eqhwj3sn60q6zqpfh542'],
  ['bc', 'bc1gmk9yu'],
  ['bc', 'bc1p0xlxvlhemja6c4dqv22uapctqupfhlxm9h8z3k2e72q4k9hcz7vqzk5jj0'],
  ['bc', 'bc1q9zpgru'],
  ['bc', 'bc1rw5uspcuh'],
  ['tb', 'tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3pjxtptv'],
  ['bc', 'bc1zw508d6qejxtdg4y5r3zarvaryvqyzf3du'],
  ['bc', 'li1dgmt3'],
  ['bc', 'a12uel5l'],
  ['a', 'a12uel5l'],
  ['an83characterlonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio', 'an83characterlonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio11sg7hg6'],
  ['split', 'split1checkupstagehandshakeupstreamerranterredcaperred2y9e3w'],
];
for (const [a, b] of NEGATIVES) {
  for (const h of new Set([a, a.toUpperCase(), swap(a)])) {
    for (const s of new Set([b, b.toUpperCase(), swap(b), flipAt(b, 0), flipAt(b, b.length - 1)])) push(h, s);
  }
}

// ---- two simultaneous case flips (still mixed case, different distances) --
{
  const base = 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4';
  for (const i of [0, 1, 3, 4, 20, base.length - 1]) {
    for (const j of [0, 1, 3, 5, 21, base.length - 2]) {
      if (i === j || !isCased(base[i]) || !isCased(base[j])) continue;
      push('bc', flipAt(flipAt(base, i), j));
      push('bc', flipAt(flipAt(base.toUpperCase(), i), j));
    }
  }
}

