import { writeFileSync } from 'node:fs';
import { segwitEncode } from '/tmp/probe/gen.mjs';
const cases=[]; const seen=new Set();
const add=(a)=>{const k=JSON.stringify(a); if(!seen.has(k)){seen.add(k);cases.push(a);}};
